-- Переводы демо-данных (ky/ru/en). Выполняется после seed.sql
update public.places set i18n = jsonb_build_object('ky', jsonb_build_object('name', name, 'description', description), 'ru', jsonb_build_object('name', 'Священная гора Сулайман-Тоо', 'description', 'Священная гора из списка Всемирного наследия ЮНЕСКО в центре города Ош.'), 'en', jsonb_build_object('name', 'Sulaiman-Too Sacred Mountain', 'description', 'A sacred mountain on the UNESCO World Heritage List, in the centre of Osh.')) where id = '00000000-0000-4000-8000-000000000001';
